exercises.solution:
V main uvnitř try použij:

```java
Path diary = Path.of("diary.txt");
Files.writeString(diary, "První zápis\n", StandardCharsets.UTF_8);
Files.writeString(diary, "Druhý zápis\n", StandardCharsets.UTF_8, StandardOpenOption.APPEND);
java.util.List<String> rows = Files.readAllLines(diary, StandardCharsets.UTF_8);
System.out.println(rows.size()); // 2
```
Při dalším běhu je počet opět 2, protože první operace obsah přepíše.

Výchozí writeString soubor přepisuje. CREATE a APPEND dovolí první i další zápis stejnou metodou. Validace musí přijít před operací, jinak by i odmítnutý vstup mohl vytvořit nebo zkrátit soubor.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    int n = Integer.parseInt(in.nextLine());
    List<String> previous = new ArrayList<>();
    for (int i = 0; i < n; i++) previous.add(in.nextLine());
    String entry = in.nextLine();
    Path dir = Files.createTempDirectory("aiva-journal-");
    Path file = dir.resolve("diary.txt");
    try {
      if (n > 0) Files.write(file, previous, StandardCharsets.UTF_8);
      try {
        Journal.append(file, entry);
        System.out.println("ULOZENO");
      } catch (IllegalArgumentException e) {
        System.out.println("ODMITNUTO");
      }
      System.out.println("Soubor: " + Files.exists(file));
      List<String> rows =
          Files.exists(file) ? Files.readAllLines(file, StandardCharsets.UTF_8) : List.of();
      System.out.println("Radky: " + rows.size());
      for (String row : rows) System.out.println("|" + row);
    } finally {
      Fixture.delete(dir);
    }
  }
}

class Fixture {
  static void delete(Path dir) throws IOException {
    try (var stream = Files.walk(dir)) {
      for (Path p : stream.sorted(Comparator.reverseOrder()).toList()) Files.deleteIfExists(p);
    }
  }
}

class Journal {
  // UPRAVUJ ODSUD
  static void append(Path file, String entry) throws IOException {
    String text = entry.trim();
    if (text.isEmpty()) throw new IllegalArgumentException("empty");
    Files.writeString(
        file,
        text + "\n",
        StandardCharsets.UTF_8,
        StandardOpenOption.CREATE,
        StandardOpenOption.APPEND);
  }
  // UPRAVUJ POTUD
}
```

Nová data nejprve připravíme stranou. Cílový soubor se mění až ve vyhrazeném kroku nahrazení. Finally odstraní dočasný soubor při úspěchu i při simulované chybě; po úspěšném move už nemusí existovat, proto deleteIfExists.

Celý soubor `Main.java` včetně připraveného kódu:

```java
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;

public class Main {
  public static void main(String[] args) throws Exception {
    Scanner in = new Scanner(System.in);
    String previous = in.nextLine(), text = in.nextLine();
    boolean fail = Boolean.parseBoolean(in.nextLine());
    Path dir = Files.createTempDirectory("aiva-draft-");
    Path file = dir.resolve("draft.txt");
    try {
      Files.writeString(file, previous, StandardCharsets.UTF_8);
      try {
        DraftStore.save(file, text, new Replacer(fail));
        System.out.println("OK");
      } catch (IllegalArgumentException e) {
        System.out.println("NEPLATNE");
      } catch (IOException e) {
        System.out.println("CHYBA");
      }
      System.out.println("Obsah: " + Files.readString(file, StandardCharsets.UTF_8));
      try (var paths = Files.list(dir)) {
        System.out.println("Docasne: " + paths.filter(p -> !p.equals(file)).count());
      }
    } finally {
      Fixture.delete(dir);
    }
  }
}

class Fixture {
  static void delete(Path dir) throws IOException {
    try (var stream = Files.walk(dir)) {
      for (Path p : stream.sorted(Comparator.reverseOrder()).toList()) Files.deleteIfExists(p);
    }
  }
}

class Replacer {
  private final boolean fail;

  Replacer(boolean fail) {
    this.fail = fail;
  }

  void replace(Path temporary, Path target) throws IOException {
    if (fail) throw new IOException("simulated replacement failure");
    Files.move(temporary, target, StandardCopyOption.REPLACE_EXISTING);
  }
}

class DraftStore {
  // UPRAVUJ ODSUD
  static void save(Path file, String text, Replacer replacer) throws IOException {
    if (text.isBlank()) throw new IllegalArgumentException("empty draft");
    Path temporary = Files.createTempFile(file.getParent(), "draft-", ".tmp");
    try {
      Files.writeString(temporary, text, StandardCharsets.UTF_8);
      replacer.replace(temporary, file);
    } finally {
      Files.deleteIfExists(temporary);
    }
  }
  // UPRAVUJ POTUD
}
```
